"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[51033],{27891(e,t,o){o.r(t),o.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>l,frontMatter:()=>r,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"general/delegated-auth-with-jumpcloud-adi","title":"Delegated Auth With Jumpcloud Adi","description":"By urvashi","source":"@site/docs/general/delegated-auth-with-jumpcloud-adi.md","sourceDirName":"general","slug":"/general/delegated-auth-with-jumpcloud-adi","permalink":"/jc-community-archive/general/delegated-auth-with-jumpcloud-adi","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Delegated Auth With Jumpcloud Adi","description":"By urvashi"},"sidebar":"docs","previous":{"title":"Defer Windows 11 Updates","permalink":"/jc-community-archive/general/defer-windows-11-updates"},"next":{"title":"Deleted","permalink":"/jc-community-archive/general/deleted"}}');var a=o(74848),i=o(28453);const r={title:"Delegated Auth With Jumpcloud Adi",description:"By urvashi"},s=void 0,h={},d=[{value:"Overview",id:"overview",level:2},{value:"Transcript",id:"transcript",level:2},{value:"Delegated Authentication",id:"delegated-authentication",level:3},{value:"Enhanced Admin Portal UI/UX",id:"enhanced-admin-portal-uiux",level:3}];function u(e){const t={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["This is an edited transcript of the ",(0,a.jsx)(t.a,{href:"https://www.youtube.com/watch?v=jWPYwBTGk80",children:"05.17.24 IT Hour"})]}),"\n",(0,a.jsx)(t.h2,{id:"overview",children:"Overview"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Sam Morgan, Principal Product Manager, talks about the Delegated Auth with the JumpCloud Active Directory Integration"}),"\n",(0,a.jsx)(t.li,{children:"She also talks about some of the UI/UX improvements made to the process of setting up and updating the Active Directory Integration"}),"\n"]}),"\n",(0,a.jsx)(t.h2,{id:"transcript",children:"Transcript"}),"\n",(0,a.jsx)(t.h3,{id:"delegated-authentication",children:"Delegated Authentication"}),"\n",(0,a.jsx)(t.p,{children:"Sam: I\u2019m here to talk about our Active Directory Integration and specifically I\u2019m here to talk about some new capabilities we\u2019re going to be releasing. They\u2019re currently in beta and are around being able to delegate the user authentication to Advice Directory. I\u2019ll dig into what that is but I\u2019ll start with what we\u2019re doing and how it\u2019s different, and then federation and why people want this. Then I\u2019ll share some changes we\u2019re making to our Active Directory setup flow in the details page to make it easier to find the information you need and to get through the flow.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"So what is Active Directory Integration? It\u2019s basically our Identity and Access Management integration that allows our customers to sync information either to or from or both ways between JumpCloud and Active Directory, specifically user and group information. It supports a variety of configurations that allow you to fill the need that you have, where that\u2019s to leave AD as your primary directory and extend that out to the cloud or on a path to migration.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"What is delegated auth? I think there\u2019s some confusion between delegation and federation and those two terms get conflated. In a federated scenario what happens is that you have a different Identity Provider and when you go to your login screen you get redirected to that other provider\u2019s login flow. You go through the login process and then you return.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"In the case of Delegated Auth, JumpCloud remains the Identity Provider. So when you go to the login screen of the user portal or device, it would be no different than what it is today. But under the covers what\u2019s happening is \u201cOh this person, we want to validate the credentials against Active Directory instead of our own system and then have that tell us that this user/credential is valid, so you can proceed with logging in and getting access to the resource that you\u2019re trying to access.\u201d Then we take you to the next step in the flow with successful validation. It\u2019s also known as pass through authentication. Basically we just use another source under the cover instead of using our own system to validate the password. In the case of validation we don\u2019t store the password. Basically there are some requirements that people sometimes have that they don't want another system to have access to that password. That\u2019s the other benefit of delegated auth and how it differs from federated.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"So why do people want this and why do we care? Previously when you installed the Active Directory Integration and you were syncing user and group information from Active Directory to JumpCloud, you had to install the import agent on all your domain controllers, because that\u2019s a requirement for Microsoft for us to be able to get and sync the password between those two systems. Now you don\u2019t have to. You can install it on a domain joined member server and you don\u2019t have to install it on all of them. So now it\u2019s much easier. You just install it on a couple of member servers to make sure you have redundancy and off you go.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"The other benefit is that the user continues to use their existing on-premise Active Directory password and the IT Admin can manage passwords that they have within Active Directory. It allows Active Directory to remain the primary source of truth and the primary authentication source for those users and we can support that more easily now from an onboarding experience. Before, if you had a group of users that already existed in Active Directory and you were bringing them into JumpCloud you had this requirement to sync the password and they had to go in and change their password. So once we release this capability they can login and we'll validate that password against theirs so they don't have to change it, they just keep doing what they do. It makes that experience much better instead of saying \u201cOh we just brought JumpCloud into our ecosystem, that\u2019s really awesome and good but you need to reset your password even if you just reset it five days ago.\u201d\xa0"}),"\n",(0,a.jsx)(t.p,{children:"It also makes it easier to extend your Active Directory to the cloud so you can do that transition more slowly and with less change management. It can act as an alternative to ADFS or some of the Okta solutions. And the latest use case that\u2019s come up is we have some customers saying they\u2019re in a multi forest environment. They have some of the forest off prem in Google Cloud and they have their on-prem and they basically don\u2019t want to have to deploy the Active Directory Integration across all their forests. They just want to have their servers log the authentication on the server and delegate to their primary on-prem environment. This also facilitates that kind of bridge between those different forests with a lot less work in terms of installation and the integration with JumpCloud.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"So now you know the \u2018why\u2019 behind this and I didn\u2019t show the experience because basically it would be no different than you logging into your user portal or device today, so not a very exciting demo.\xa0"}),"\n",(0,a.jsx)(t.h3,{id:"enhanced-admin-portal-uiux",children:"Enhanced Admin Portal UI/UX"}),"\n",(0,a.jsx)(t.p,{children:"I also want to talk about some enhancements that we\u2019re making to complement these additional changes. We made these changes because right now when you finish getting your domain added to JumpCloud for the integration, we drop you onto the downloads page. And then every time you go back, you continue to go to the downloads page even though you\u2019ve done the installation and the information you need is on a different tab. So we\u2019re trying to bring all that more front and center, make it easier after you complete your installation to see the information you need to monitor the health of your integration and then have the actions you might need to do easily accessible but in lower prevalence on the screen.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"And there\u2019s some things that we do that just happen in the background, so we\u2019re trying to bring all of that to the forefront so you\u2019re aware of what is on or off even if you can\u2019t change it at least you have the understanding of what it is and how it could impact the behavior of the integration. Trying to make it a little bit more obvious when actions are needed.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"The other thing is if you\u2019re going through a migration - Active Directory is my primary directory to start but I\u2019m eventually going to migrate or reduce the footprint of Active Directory in my environment or eventually migrate off of it - you may need to change your Active Directory Integration configuration as you move through that journey. So now we\u2019re going to have flows that help you move through that journey as well.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"So when you login and you say \u201cI want to add an Active Directory Integration\u201d we\u2019re going to ask what you\u2019re trying to do, where you want to manage your groups/passwords/users. Is it JumpCloud, Active Directory or both? Then we ask you for your domain and then we give you confirmation that says \u201cokay, this is what you said, this means that the password is going to be managed in this directory and this is the way it\u2019s going to sync\u201d. If you choose JumpCloud then you say \u201cOkay JumpCloud is going to be the password authority and the direction is going to be from JumpCloud to Active Directory\u201d So we give you a visual of what it is and tell you the agents that you need for this deployment. If it\u2019s a two way sync, you need both agents. If It's one or the other, we only show the download for one.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Then you click Configure, you download those agents, you go off and do your stuff in Active Directory and then instead of being on the downloads tab, we say \u201cokay here\u2019s what it looks like in terms of what agents you have installed, whether they\u2019re active/pending/inactive, whether there\u2019s an update available\u201d, some more information about the versions, the IP sources, you get to see all that front and center. Then if you need to do an update you\u2019re going to have the ability to say \u201cHey I\u2019m going to update my existing agents\u201d which means you have less information that you\u2019re going to need to enter. If you\u2019re installing a new server we give you the full information that you need - like your connect keys, API keys, and org IDs.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Then in the Integration section we\u2019re going to bring forward the capabilities to either toggle on or off or that are set for your particular configuration - like managing groups, syncing those groups from JumpCloud to AD, or setting AD as the password authority so that no changes to the password can be made in JumpCloud. We\u2019re bringing all those configurations forward so it\u2019s more obvious what you can and can\u2019t do.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"Back at the top there\u2019s the Update Configuration button which is new. There\u2019s some reminders of what your domain is, which directory is acting as the primary source of truth or if it\u2019s a shared responsibility, and a reminder of the sync directions. Then if you\u2019re ready to change your configuration, say you\u2019re bidirectional and you want JumpCloud to be the sole authority, you can update your configuration. Click the button, it\u2019ll show you your current configuration and then you have two options to choose from. Once you select that we\u2019ll show you what your previous configuration is and what your updated configuration is and we\u2019ll have some reminders around uninstalling extra agents and reminders for next steps and then confirmation. If you need to install a new agent we\u2019ll show you what that agent is and remind you how this change might impact your users.\xa0"}),"\n",(0,a.jsx)(t.p,{children:"For example if you had the passwords and attributes locked down and you\u2019re moving to a more flexible option where they can be changed in JumpCloud, we\u2019ll say \u201cHey we\u2019re going to update all your associated users that they can make changes to their password in JumpCloud, which they couldn\u2019t do before.\u201d. If you\u2019re going the other way where you previously allowed users to change their passwords and now you don\u2019t want to do that, we\u2019ll update them so that they\u2019re no longer allowed to update their passwords in JumpCloud and it\u2019s restricted to changes in Active Directory. So just more communication, more automation. Before, it was an API call that you had to make, run a PowerShell script etc. now we\u2019re going to do a lot of that heavy lifting for you."})]})}function l(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}},28453(e,t,o){o.d(t,{R:()=>r,x:()=>s});var n=o(96540);const a={},i=n.createContext(a);function r(e){const t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),n.createElement(i.Provider,{value:t},e.children)}}}]);